const BUILD = "CDF-V12.5-DIRECT-WORKER";
const THREE_VERSION = "0.181.2";
const GAME_HTML_B64 = "";

function gameHtml() {
  const bytes = Uint8Array.from(atob(GAME_HTML_B64), c => c.charCodeAt(0));
  return new TextDecoder().decode(bytes);
}
function txt(body,status=200,headers={}) { return new Response(body,{status,headers:{"content-type":"text/plain; charset=utf-8","cache-control":"no-store",...headers}}); }
async function proxyThree(request,url) {
  const prefix='/vendor/three/';
  const rel=url.pathname.slice(prefix.length);
  if(!rel || rel.includes('..') || !/^[A-Za-z0-9_./-]+$/.test(rel)) return txt('Invalid vendor path',400,{'x-cdf-build':BUILD});
  const upstream=`https://cdn.jsdelivr.net/npm/three@${THREE_VERSION}/${rel}`;
  try {
    const r=await fetch(upstream,{method:request.method==='HEAD'?'HEAD':'GET',headers:{accept:'*/*'},cf:{cacheEverything:true,cacheTtl:604800}});
    if(!r.ok) return txt(`Three upstream ${r.status}: ${rel}`,502,{'x-cdf-build':BUILD});
    const h=new Headers(r.headers); h.set('cache-control','public,max-age=604800,immutable'); h.set('access-control-allow-origin','*'); h.set('x-cdf-build',BUILD);
    if(rel.endsWith('.js')) h.set('content-type','text/javascript; charset=utf-8');
    return new Response(request.method==='HEAD'?null:r.body,{status:200,headers:h});
  } catch(e) { return txt(`Proxy fetch failed: ${e?.message||e}`,502,{'x-cdf-build':BUILD}); }
}
export default {
 async fetch(request) {
   const url=new URL(request.url);
   // diagnostics MUST win before any HTML route
   if(url.pathname==='/build-id.txt') return txt(BUILD+'\n',200,{'x-cdf-build':BUILD});
   if(url.pathname==='/__cdf_status') return new Response(JSON.stringify({build:BUILD,worker:true,threeVersion:THREE_VERSION,path:url.pathname,time:new Date().toISOString()},null,2),{headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store','x-cdf-build':BUILD}});
   if(url.pathname.startsWith('/vendor/three/')) return proxyThree(request,url);
   if(url.pathname==='/home') return Response.redirect(new URL('/?home=1',url),302);
   if(request.method!=='GET' && request.method!=='HEAD') return txt('Method not allowed',405,{'x-cdf-build':BUILD});
   const h=new Headers({'content-type':'text/html; charset=utf-8','cache-control':'no-store, no-cache, must-revalidate, max-age=0','pragma':'no-cache','expires':'0','x-cdf-build':BUILD});
   return new Response(request.method==='HEAD'?null:gameHtml(),{status:200,headers:h});
 }
};
